#!/usr/bin/env bash
# AgentEnhancements Unified Launcher
# Generated by native_integration.py

set -euo pipefail

AE_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
export AGENT_ENHANCEMENTS_BASE_DIR="$AE_ROOT"
export AGENT_MEMORY_ROOT="$AE_ROOT/.agentenhancements/memory"
export AE_MAX_SKILL_CARDS=8
export AE_PREFLIGHT_DEADLINE_MS=2000

# Load runtime config if exists
RUNTIME_CONFIG="$AE_ROOT/unified-integration/config/runtime.json"
if [[ -f "$RUNTIME_CONFIG" ]]; then
    # Export config values as env vars
    export AE_COMPRESSION_BUDGET=$(jq -r '.compression_budget // 200000' "$RUNTIME_CONFIG")
    export AE_COMPRESSION_TRIGGER=$(jq -r '.compression_trigger // 0.75' "$RUNTIME_CONFIG")
    export AE_PREFLIGHT_MODE=$(jq -r '.preflight_mode // 0' "$RUNTIME_CONFIG")
fi

usage() {
    cat <<EOF
Usage: $0 <agent> [args...]

Launch an AI coding agent with AgentEnhancements integration.

Agents:
  claude-code, claude    - Anthropic Claude Code
  codex                  - OpenAI Codex CLI
  opencode               - OpenCode 2
  hermes                 - Hermes
  cursor                 - Cursor
  gemini                 - Google Gemini CLI
  copilot                - GitHub Copilot CLI
  windsurf               - Windsurf
  kiro                   - Kiro

Environment:
  AGENT_ENHANCEMENTS_BASE_DIR  - AE root directory (auto-set)
  AGENT_MEMORY_ROOT            - Memory database directory (auto-set)
  AE_MAX_SKILL_CARDS           - Max skill cards per prompt (default: 8)
  AE_PREFLIGHT_MODE            - Preflight mode: 0=legacy, 1=native, 2=custom (default: 0)
  AE_PREFLIGHT_DEADLINE_MS     - Preflight deadline in ms (default: 2000)

Examples:
  $0 claude-code
  $0 codex --model gpt-4
  $0 opencode --config ~/.config/opencode/opencode.jsonc
EOF
}

if [[ $# -eq 0 ]]; then
    usage
    exit 1
fi

AGENT="$1"
shift

case "$AGENT" in
    claude|claude-code)
        exec claude "$@"
        ;;
    codex)
        exec codex "$@"
        ;;
    opencode)
        exec opencode "$@"
        ;;
    hermes)
        exec hermes "$@"
        ;;
    cursor)
        exec cursor "$@"
        ;;
    gemini)
        exec gemini "$@"
        ;;
    copilot)
        exec gh copilot "$@"
        ;;
    windsurf)
        exec windsurf "$@"
        ;;
    kiro)
        exec kiro "$@"
        ;;
    *)
        echo "Error: Unknown agent '$AGENT'" >&2
        usage
        exit 1
        ;;
esac